'use strict';
areaStyle=function(f){if(!liveMode)return original.areaStyle(f);const n=liveSnapshot?.neighbourhoods.find(n=>n.name===f.properties.name);const v=layerMode==='construction'?n?.construction:layerMode==='service'?n?.departures:n?.closures;const color=v===null||v===undefined?'#aeb7b0':layerMode==='service'?(v>=100?'#d4ad55':'#65a88b'):v>=3?'#ce7757':v>=1?'#d4ad55':'#65a88b';return {color:f.properties.name===selected?'#365743':'#fff',weight:f.properties.name===selected?2:1.4,fillColor:color,fillOpacity:.38}};
initMap=function(){if(liveMode&&!['closures','construction','service'].includes(layerMode))layerMode='closures';if(!liveMode&&!['activity','anomaly','transit'].includes(layerMode))layerMode='activity';original.initMap();if(!map)return;if(liveMode){$('#map-layer').onchange=e=>{layerMode=e.target.value;areas.setStyle(f=>areaStyle(f));updateRoadLines();$('#live-map-key').innerHTML=layerMode==='service'?'<span><i></i>0–99 stops/hr</span><span><i class="busy"></i>100+</span>':'<span><i></i>0 reports</span><span><i class="busy"></i>1–2</span><span><i class="high"></i>3+</span>'};updateRoadLines()}};
function updateRoadLines(){if(roadLayer){roadLayer.remove();roadLayer=null}if(!liveMode||!map||!liveSnapshot||layerMode==='service')return;const kind=layerMode==='construction'?'construction':'closure';const features=liveSnapshot.neighbourhoods.flatMap(n=>n.projects.filter(p=>p.type===kind&&p.geometry).map(p=>({type:'Feature',geometry:p.geometry,properties:{name:n.name,title:p.title}})));roadLayer=L.geoJSON({type:'FeatureCollection',features},{style:{color:kind==='closure'?'#ad654d':'#b78a43',weight:2.4,opacity:.8},onEachFeature:(f,l)=>{l.bindTooltip(esc(f.properties.title));l.on('click',()=>detail(f.properties.name))}}).addTo(map)}
render=function(){view=location.hash.slice(1);if(!views[view])view='overview';if(map){map.remove();map=null;roadLayer=null}const labels={overview:'Overview',neighbourhoods:'Neighbourhoods',forecast:'Forecasts',anomalies:'Anomalies',history:'Historical patterns',sources:'Data sources',models:'Model performance'};$('#page-title').textContent=labels[view];$('#crumb').textContent=labels[view];$$('[data-view]').forEach(a=>a.classList.toggle('active',a.dataset.view===view));$('#content').innerHTML=({overview,neighbourhoods,forecast,anomalies:anomalyPage,history,sources,models})[view]();$('#nav-count').textContent=liveMode?(liveSnapshot?.neighbourhoods.filter(n=>n.unusual).length||'—'):anomalies(30).length;$('#footer-note').textContent=liveMode?'Vancouver city coverage · source publication times vary':'Synthetic observations · model demonstration';if($('#data-mode'))$('#data-mode').value=liveMode?'live':'demo';if(view==='overview')initMap();if(view==='neighbourhoods'){const filter=()=>{const rows=(liveMode?liveSnapshot?.neighbourhoods||[]:data.neighbourhoods).filter(n=>n.name.toLowerCase().includes($('#search').value.toLowerCase()));const key=$('#sort').value;rows.sort((a,b)=>key==='name'?a.name.localeCompare(b.name):(b[key]??-1)-(a[key]??-1));$('#neighbourhood-table').innerHTML=rows.length?evidenceTable(rows):'<p class="muted">No neighbourhoods match your search.</p>'};$('#search').oninput=filter;$('#sort').onchange=filter}if(view==='forecast')$('#forecast-area').onchange=e=>$('#forecast-body').innerHTML=forecastBody(e.target.value);if(view==='anomalies'&&!liveMode)$('#severity').onchange=e=>$('#anomaly-table').innerHTML=evidenceTable(anomalies(30).filter(n=>e.target.value==='all'||n.activity>(n.typical_range?.[1]??100)))};
async function auxiliary(){const base=liveConfig.data_base||'';for(const [file,set] of [['live-history.json',v=>liveHistory=v],['transit-schedule.json',v=>transitSchedule=v]]){try{const r=await fetch(base+file,{cache:'no-store',signal:AbortSignal.timeout(15000)});if(r.ok)set(await r.json())}catch{}}}
async function refreshLive(force=false){if(refreshing||(!force&&Date.now()-lastFetch<300000))return;refreshing=true;const b=$('#refresh-live');if(b){b.disabled=true;b.textContent='Refreshing…'}try{await auxiliary();liveSnapshot=await CityPulseLive.collect(geo,{previous:liveSnapshot,history:liveHistory,schedule:transitSchedule});lastFetch=Date.now();if(liveMode){if(view==='overview'&&map){const holder=document.createElement('div');holder.innerHTML=liveStatus()+liveExceptions();$('.status-region').replaceWith($('.status-region',holder));$('.exception-panel').replaceWith($('.exception-panel',holder));$('#analysis-area').innerHTML=analysisContent();areas.setStyle(f=>areaStyle(f));updateRoadLines()}else if(document.activeElement?.id!=='search')render()}}catch(e){notify('Source refresh failed. Last available observations retained.');console.warn(e)}finally{refreshing=false;const button=$('#refresh-live');if(button){button.disabled=false;button.textContent='↻ Refresh'}}}
document.addEventListener('click',e=>{const a=e.target.closest('[data-analysis]');if(a)analysisDialog(a.dataset.analysis,!!a.dataset.demoAnalysis);if(e.target.closest('#refresh-live'))refreshLive(true)});
$('#about').onclick=()=>{$('#detail-content').innerHTML='<div class="detail-eyebrow">CITYPULSE</div><h2>Vancouver urban intelligence</h2><p class="muted">Live sources combines official municipal road reports, current modelled weather and scheduled transit service. Sources are checked every five minutes. Model demo is a separate, labelled synthetic dataset. Select a neighbourhood to inspect evidence below the map.</p>';$('#detail').showModal()};
$('#export').onclick=()=>{const value=liveMode?liveSnapshot:data;if(!value)return;const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`citypulse-${liveMode?'live':'demo'}-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Snapshot exported with source timestamps')};
async function initializeConsole(){try{const get=async(p,fallback)=>{try{const r=await fetch(p);return r.ok?await r.json():fallback}catch{return fallback}};[data,geo,liveSnapshot,liveHistory,transitSchedule,liveConfig]=await Promise.all([get('snapshot.json',null),get('neighbourhoods.geojson',null),get('live-snapshot.json',null),get('live-history.json',[]),get('transit-schedule.json',null),get('config.json',{})]);if(!data||!geo)throw Error('Required workspace data unavailable');if(liveSnapshot)CityPulseLive.enrich(liveSnapshot,liveHistory,transitSchedule);$('.heading-actions').insertAdjacentHTML('afterbegin','<select class="select" id="data-mode" aria-label="Data mode"><option value="live">Live sources</option><option value="demo">Model demo</option></select>');$('#data-mode').onchange=e=>{liveMode=e.target.value==='live';render()};render();window.addEventListener('hashchange',render);refreshLive(true);setInterval(()=>{if(!document.hidden)refreshLive()},60000);setInterval(()=>$$('[data-age]').forEach(el=>el.textContent=age(el.dataset.age)),30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshLive()});
if(document.modelContext?.registerTool){try{await document.modelContext.registerTool({name:'inspect_neighbourhood',description:'Select a neighbourhood and display its evidence below the map in the active live or demo dataset.',inputSchema:{type:'object',properties:{name:{type:'string'}},required:['name'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async({name})=>{if(typeof name!=='string'||!(liveMode?liveSnapshot?.neighbourhoods:data.neighbourhoods)?.some(n=>n.name===name))throw Error('Unknown neighbourhood');selected=name;if(view!=='overview'){window.history.replaceState(null,'','#overview');render()}else detail(name);const n=currentArea();return {name,mode:liveMode?'live':'demo',closures:liveMode?n.closures:undefined,activity:liveMode?undefined:n.activity}}})}catch(e){console.warn('Optional agent interface unavailable',e)}}
}catch(e){$('#content').innerHTML='<article class="card full-panel"><h2>Workspace unavailable</h2><p>Reload to retry loading the workspace data.</p></article>';console.error(e)}}
initializeConsole();
